<?php
$home = $GLOBALS['nhk_v3_home_data'] ?? null;
$sidebar = is_array($home) && is_array($home['sidebar'] ?? null) ? $home['sidebar'] : [];
$groups = nhk_v3_navigation_groups();
$primaryLookup = array_slice(array_values((array) ($groups['primary'] ?? [])), 0, 4);
$secondaryLookup = array_values(array_filter((array) ($groups['discovery'] ?? []), static fn (mixed $item): bool => is_array($item) && in_array((string) ($item['label'] ?? ''), ['Hình ảnh', 'Video', 'Mẫu', 'Bộ máy'], true)));
?>
<aside class="sidebar" aria-label="Khám phá thêm"><section class="sidebar-block"><p class="eyebrow">Tra cứu</p><h2>Đi sâu hơn</h2><nav class="topic-list"><?php foreach (array_merge($primaryLookup, $secondaryLookup) as $item): $url = nhk_v3_public_url($item['path'] ?? null); if ($url === '') continue; ?><a href="<?php echo esc_url($url); ?>"><?php echo esc_html((string) ($item['label'] ?? '')); ?> <span>→</span></a><?php endforeach; ?><?php foreach (nhk_v3_clock_type_navigation_items('sidebar') as $item): $url = nhk_v3_public_url($item['path'] ?? null); if ($url === '') continue; ?><a href="<?php echo esc_url($url); ?>"><?php echo esc_html((string) $item['label']); ?> <span>→</span></a><?php endforeach; ?></nav></section><?php if ($sidebar !== []): ?><section class="sidebar-block"><p class="eyebrow">Đọc tiếp</p><h2>Bài mới</h2><ol class="sidebar-posts"><?php global $post; foreach ($sidebar as $post): setup_postdata($post); ?><li><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a><time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(nhk_v3_public_date()); ?></time></li><?php endforeach; wp_reset_postdata(); ?></ol></section><?php endif; ?></aside>
